pm.test("Availability returns 200", function () { pm.response.to.have.status(200); });

const data = pm.response.json().data;
const availableTime = (data.times || []).find(slot => slot.is_available);
pm.test("A bookable slot exists", function () { pm.expect(data.days.length).to.be.above(0); pm.expect(availableTime).to.exist; });
if (data.days.length && availableTime) {
    pm.collectionVariables.set("visitDate", data.days[0].visit_date);
    pm.collectionVariables.set("visitTime", availableTime.visit_time);
}

